export function getPromptTemplate(id) {
  return AI_GENERATOR_DB.prompt_templates.find((item) => item.id === id) || null;
}

export function listPromptTemplates(filters = {}) {
  const { category, type, model, style, search } = filters;
  const query = String(search || '').trim().toLowerCase();
  return AI_GENERATOR_DB.prompt_templates.filter((item) => {
    if (!item.enabled) return false;
    if (category && item.category !== category) return false;
    if (type && item.type !== type) return false;
    if (model && item.default_model !== model) return false;
    if (style && item.default_style !== style) return false;
    if (query) {
      const haystack = [item.id, item.name, ...(item.tags || [])].join(' ').toLowerCase();
      if (!haystack.includes(query)) return false;
    }
    return true;
  });
}

export function getStylePreset(id) {
  return AI_GENERATOR_DB.style_presets.find((style) => style.id === id) || null;
}

export function renderPrompt(template, values = {}) {
  if (!template) throw new Error('Prompt template is required.');
  const source = typeof template === 'string' ? template : template.prompt_template;
  return String(source).replace(/\[([A-Z0-9_ /-]+)\]|\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/g, (match, squareKey, moustacheKey) => {
    const key = (moustacheKey || squareKey || '').trim();
    const direct = values[key];
    const normalized = values[key.toLowerCase().replace(/[^a-z0-9]+/g, '_')];
    return direct ?? normalized ?? match;
  });
}

export function buildGenerationRequest({ templateId, values = {}, model, style, aspectRatio } = {}) {
  const template = getPromptTemplate(templateId);
  if (!template) throw new Error(`Unknown prompt template: ${templateId}`);
  const selectedStyle = getStylePreset(style || template.default_style || AI_GENERATOR_DB.defaults.style);
  const basePrompt = renderPrompt(template, values).trim();
  const prompt = [basePrompt, selectedStyle?.prompt_suffix].filter(Boolean).join(', ');
  return {
    template_id: template.id,
    model: model || template.default_model || AI_GENERATOR_DB.defaults.model,
    aspect_ratio: aspectRatio || template.aspect_ratio || AI_GENERATOR_DB.defaults.aspect_ratio,
    prompt,
    negative_prompt: template.negative_prompt || '',
    requires_reference_image: Boolean(template.requires_reference_image),
  };
}
